UPDATE text_game_story_versions
SET story_json = #{storyJson}, checksum = #{checksum}, revision = revision + 1
WHERE id = #{id} AND status = 'DRAFT' AND revision = #{expectedRevision}

UPDATE text_game_story_versions
SET status = 'PUBLISHED', published_at = #{publishedAt}, revision = revision + 1
WHERE id = #{id} AND status = 'DRAFT' AND revision = #{expectedRevision}

UPDATE text_game_stories
SET title = #{title}, summary = #{summary}, enabled = #{enabled}, sort_order = #{sortOrder}
WHERE id = #{id}

UPDATE text_game_sessions
SET current_node_id = #{currentNodeId}, pending_node_id = #{pendingNodeId}, phase = #{phase},
    attributes_json = #{attributesJson}, relations_json = #{relationsJson},
    flags_json = #{flagsJson}, history_json = #{historyJson}, result_json = #{resultJson},
    revision = revision + 1, expires_at = #{expiresAt}, completed_at = #{completedAt}
WHERE session_id = #{sessionId} AND revision = #{revision}
